package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.Context;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.function.*;

/** Board 07. Only an explicit Preview action may allocate a cue output. */
public final class SnoringCuesActivity extends Activity {
    interface PreviewFactory {SnoreCuePolicy.Device create(Context context,BooleanSupplier allowed);}
    static PreviewFactory previewFactory=SnoreCueOutput::new;
    static LongSupplier previewClock=SystemClock::elapsedRealtime;
    // Process-local and independent of the real night's budget; no Activity or output token.
    static SnoreCuePolicy.Budget previewBudget=new SnoreCuePolicy.Budget();
    private PreviewFactory output;private LongSupplier elapsed;private SnoreCuePolicy.Budget budget;private SnoreCuePolicy preview;
    private volatile boolean previewLive;private boolean resumed;private Dialog about;private TextView feedback;
    private boolean enabled,analysis;private int mode,intensity,repeats,sensitivity;private String error="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);output=previewFactory;elapsed=previewClock;budget=previewBudget;enabled=saved==null?Prefs.flag(this,"snoreCues"):saved.getBoolean("enabled");analysis=saved==null?Prefs.flag(this,"noiseEnabled"):saved.getBoolean("analysis");mode=saved==null?Prefs.number(this,"snoreCueMode",1):saved.getInt("mode");intensity=saved==null?Prefs.number(this,"snoreCueIntensity",1):saved.getInt("intensity");repeats=saved==null?Prefs.number(this,"snoreCueRepeats",1):saved.getInt("repeats");sensitivity=saved==null?Prefs.number(this,"snoreCueSensitivity",1):saved.getInt("sensitivity");mode=Math.max(0,Math.min(2,mode));intensity=Math.max(1,Math.min(3,intensity));repeats=Math.max(1,Math.min(3,repeats));sensitivity=Math.max(0,Math.min(2,sensitivity));render();}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putBoolean("enabled",enabled);out.putBoolean("analysis",analysis);out.putInt("mode",mode);out.putInt("intensity",intensity);out.putInt("repeats",repeats);out.putInt("sensitivity",sensitivity);}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);LinearLayout header=RecordUi.header(body,"Snoring cues",this::finish);RecordUi.headerAction(header,"info","About snoring cues",()->about=SleepPicker.message(this,"About snoring cues","Snoring labels are estimates, not a diagnosis. Sound uses your media volume. Night cues and explicit previews have separate two-minute cooldowns and limits of 30 per session or app process. A preview requests one short cue at low intensity without starting the microphone or saving this draft."));
        Design.toggle(body,"Respond to snoring estimates","A short cue may help you change position.",enabled,on->enabled=on);Design.space(body,10);
        section(body,"wave","Alert type",null);alertCards(body);
        section(body,"vibrate","Intensity",mode==0?"How strong the sound feels.":mode==1?"How strong the vibration feels.":"Strength of sound and vibration.");choices(body,"Intensity",new String[]{"Low","Medium","High"},intensity-1,n->{intensity=n+1;render();});
        section(body,"clock","Repeats","How many times to alert.");choices(body,"Repeats",new String[]{"1","2","3"},repeats-1,n->{repeats=n+1;render();});
        section(body,"wave","Detection sensitivity","How easily snoring is detected.");choices(body,"Detection sensitivity",new String[]{"Low","Medium","High"},sensitivity,n->{sensitivity=n;render();});
        Design.space(body,6);microphone(body);Design.line(body);previewRow(body);
        feedback=Design.text(body,error,12,500,Design.BROWN);feedback.setVisibility(error.isEmpty()?View.GONE:View.VISIBLE);String failure=Prefs.text(this,"snoreCueError","");if(!failure.isEmpty())Design.text(body,failure,12,500,Design.BROWN);
        Design.fixedAction(body,"Save settings",this::save);
    }
    private void section(LinearLayout body,String icon,String title,String helper){Design.space(body,10);LinearLayout row=Design.row(this);LinearLayout.LayoutParams glyph=new LinearLayout.LayoutParams(Design.dp(this,23),Design.dp(this,23));glyph.rightMargin=Design.dp(this,14);row.addView(new Design.Icon(this,icon,Design.BROWN),glyph);LinearLayout copy=Design.col(this);Design.text(copy,title,15,600,Design.INK);if(helper!=null){Design.space(copy,3);Design.text(copy,helper,11,400,Design.MUTED);}row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));body.addView(row);Design.space(body,3);}
    private FrameLayout hit(String title,boolean selected,android.view.View face,int height,Runnable click,int index,int size){FrameLayout hit=new FrameLayout(this);hit.setContentDescription(title);hit.setSelected(selected);hit.setFocusable(true);FrameLayout.LayoutParams visual=new FrameLayout.LayoutParams(-1,Design.dp(this,height),Gravity.CENTER);visual.setMargins(Design.dp(this,index==0?0:3),0,Design.dp(this,index==size-1?0:3),0);hit.addView(face,visual);hit.setOnClickListener(v->{closePreview();click.run();});return hit;}
    private void alertCards(LinearLayout body){LinearLayout group=Design.row(this);group.setContentDescription("Alert type options");String[] titles={"Sound","Vibration","Both"};for(int n=0;n<3;n++){int index=n,color=n==mode?Design.CREAM:Design.BROWN;LinearLayout face=Design.col(this);face.setGravity(Gravity.CENTER);face.setBackground(Design.touch(this,n==mode?Design.BROWN:Design.SOFT,12));LinearLayout icons=Design.row(this);icons.setGravity(Gravity.CENTER);if(n!=1)icons.addView(new Design.Icon(this,"sound",color),new LinearLayout.LayoutParams(Design.dp(this,22),Design.dp(this,22)));if(n==2){LinearLayout.LayoutParams gap=new LinearLayout.LayoutParams(Design.dp(this,12),Design.dp(this,12));gap.setMargins(Design.dp(this,3),0,Design.dp(this,3),0);icons.addView(new Design.Icon(this,"plus",color),gap);}if(n!=0)icons.addView(new Design.Icon(this,"vibrate",color),new LinearLayout.LayoutParams(Design.dp(this,22),Design.dp(this,22)));face.addView(icons);Design.space(face,5);Design.text(face,titles[n],12,n==mode?600:400,n==mode?Design.CREAM:Design.INK).setGravity(Gravity.CENTER);group.addView(hit(titles[n],n==mode,face,64,()->{mode=index;render();},n,3),new LinearLayout.LayoutParams(0,Design.dp(this,72),1));}body.addView(group);}
    private void choices(LinearLayout body,String section,String[] labels,int value,IntConsumer change){LinearLayout group=Design.row(this);group.setContentDescription(section+" options");for(int n=0;n<labels.length;n++){int index=n;TextView face=Design.text(this,labels[n],12,n==value?600:400,n==value?Design.CREAM:Design.INK);face.setGravity(Gravity.CENTER);face.setBackground(Design.touch(this,n==value?Design.BROWN:Design.SOFT,10));group.addView(hit(labels[n],n==value,face,32,()->change.accept(index),n,labels.length),new LinearLayout.LayoutParams(0,Design.dp(this,48),1));}LinearLayout.LayoutParams inset=new LinearLayout.LayoutParams(-1,-2);inset.leftMargin=Design.dp(this,37);body.addView(group,inset);}
    private void microphone(LinearLayout body){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,62));LinearLayout.LayoutParams icon=new LinearLayout.LayoutParams(Design.dp(this,23),Design.dp(this,23));icon.rightMargin=Design.dp(this,14);row.addView(new Design.Icon(this,"search",Design.BROWN),icon);LinearLayout copy=Design.col(this);Design.text(copy,"Requires sound analysis",14,600,Design.INK);Design.space(copy,3);Design.text(copy,"On-device analysis while you sleep.",11,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));Switch toggle=new Switch(this);toggle.setContentDescription("Microphone analysis");Design.styleSwitch(this,toggle,Design.BROWN,0xffbcb5b0);toggle.setChecked(analysis);toggle.setOnCheckedChangeListener((v,on)->{if(on&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){analysis=false;render();requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},104);}else analysis=on;});row.addView(toggle);body.addView(row);}
    private void previewRow(LinearLayout body){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,62));FrameLayout button=new FrameLayout(this);button.setContentDescription("Preview cue");button.setFocusable(true);Design.Icon icon=new Design.Icon(this,"play",Design.BROWN);icon.setBackground(Design.touch(this,Design.SOFT,24));button.addView(icon,new FrameLayout.LayoutParams(Design.dp(this,42),Design.dp(this,42),Gravity.CENTER));row.addView(button,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));LinearLayout copy=Design.col(this);copy.setPadding(Design.dp(this,10),0,0,0);Design.text(copy,"Preview cue",14,600,Design.INK);Design.space(copy,3);Design.text(copy,"One short cue at low intensity.",11,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));button.setOnClickListener(v->preview());body.addView(row);}
    private void preview(){if(!previewLive||TrackingService.running||Prefs.flag(this,"ringing")){message("End tracking or the alarm before previewing.");return;}if(preview==null){Context app=getApplicationContext();preview=new SnoreCuePolicy(budget,()->output.create(app,()->previewLive&&!TrackingService.running&&!Prefs.flag(app,"ringing")),()->message("The preview could not start."));}SnoreCuePolicy.Mode type=mode==0?SnoreCuePolicy.Mode.SOUND:mode==2?SnoreCuePolicy.Mode.BOTH:SnoreCuePolicy.Mode.VIBRATION;boolean started=preview.event("snoring",1,elapsed.getAsLong(),SnoreCuePolicy.previewSettings(type,sensitivity));if(started)message("Preview requested at low intensity.");else if(!error.equals("The preview could not start."))message("Wait two minutes before previewing again.");}
    private void message(String value){error=value;if(feedback!=null){feedback.setText(value);feedback.setVisibility(View.VISIBLE);}}
    private void closePreview(){if(preview!=null){preview.close();preview=null;}}
    private void save(){if(enabled&&(!analysis||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)){message("Enable microphone analysis to use cues.");return;}Prefs.of(this).edit().putBoolean("snoreCues",enabled).putBoolean("noiseEnabled",analysis).putInt("snoreCueMode",mode).putInt("snoreCueIntensity",intensity).putInt("snoreCueRepeats",repeats).putInt("snoreCueSensitivity",sensitivity).apply();finish();}
    @Override protected void onResume(){super.onResume();resumed=true;previewLive=hasWindowFocus();}
    @Override protected void onPause(){resumed=false;previewLive=false;closePreview();super.onPause();}
    @Override protected void onDestroy(){previewLive=false;closePreview();if(about!=null)about.dismiss();super.onDestroy();}
    @Override public void onRequestPermissionsResult(int request,String[] names,int[] grants){super.onRequestPermissionsResult(request,names,grants);if(request==104){analysis=grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED;if(!analysis)error="Microphone access is off. You can enable it in Android settings.";render();}}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);previewLive=focused&&resumed;if(focused)RecordUi.lightBars(this);else closePreview();}
}
